-- Role-switching RLS test (plain Postgres + local_stubs.sql). Prints PASS/FAIL lines.
\set QUIET on
reset role;
create or replace function pg_temp.ok(name text, cond boolean) returns text language sql as $$ select (case when cond then 'PASS ' else 'FAIL ' end)||name $$;
create or replace function pg_temp.fails(name text, stmt text) returns text language plpgsql as $$ begin execute stmt; return 'FAIL '||name||' (was allowed)'; exception when others then return 'PASS '||name||' ('||left(sqlerrm,60)||')'; end $$;
delete from auth.users where email like '%@rls.test';
insert into auth.users(id,email) values
 ('a0000000-0000-0000-0000-000000000001','admin@rls.test'),('a0000000-0000-0000-0000-000000000002','md@rls.test'),
 ('a0000000-0000-0000-0000-000000000003','mkt@rls.test'),('a0000000-0000-0000-0000-000000000004','mkt2@rls.test'),
 ('a0000000-0000-0000-0000-000000000005','cost@rls.test'),('a0000000-0000-0000-0000-000000000006','plan@rls.test'),
 ('a0000000-0000-0000-0000-000000000007','disp@rls.test'),('a0000000-0000-0000-0000-000000000008','factory@rls.test'),('a0000000-0000-0000-0000-000000000009','gone@rls.test');
update profiles set role='hr_admin' where email='admin@rls.test'; update profiles set role='md' where email='md@rls.test';
update profiles set role='marketing' where email in ('mkt@rls.test','mkt2@rls.test','gone@rls.test'); update profiles set role='costing' where email='cost@rls.test';
update profiles set role='planning' where email='plan@rls.test'; update profiles set role='dispatch' where email='disp@rls.test'; update profiles set role='factory_manager' where email='factory@rls.test';
update profiles set active=false where email='gone@rls.test';
select pg_temp.ok('profiles auto-created by auth trigger',(select count(*) from profiles where email like '%@rls.test')=9);

-- marketing creates enquiry (number from DB), costing adds costing, marketing quotes
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
insert into enquiries(customer_id,product,qty,value,owner_id,next_action,due_date) values('00000000-0000-0000-0000-000000000c01','RLS test pouch',5000,100000,'a0000000-0000-0000-0000-000000000003','call',current_date);
select pg_temp.ok('marketing: enquiry number generated by DB',(select enq_no ~ '^ENQ-\d{4}-\d{4}$' from enquiries where product='RLS test pouch'));
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000005',false); set role authenticated;
select pg_temp.fails('costing: cannot create customer',$$insert into customers(name,mobile) values('x','1')$$);
insert into costings(enquiry_id,material,cost_per_kg,price_per_kg) select id,150,150,180 from enquiries where product='RLS test pouch';
insert into costing_margins(costing_id,margin_pct) select id,20 from costings;
select pg_temp.ok('costing: sees costing and margins',(select count(*) from costing_margins)>0);
select pg_temp.fails('costing: cannot issue quotation',$$insert into quotations(enquiry_id,price_per_kg) select id,200 from enquiries where product='RLS test pouch'$$);
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
select pg_temp.ok('marketing: costing table hidden',(select count(*) from costings)=0);
select pg_temp.ok('marketing: costing margins hidden',(select count(*) from costing_margins)=0);
insert into quotations(enquiry_id,price_per_kg,qty,terms,needs_approval) select id,155,'5000','advance',false from enquiries where product='RLS test pouch';
select pg_temp.ok('marketing: low-margin quote flagged by DB despite client sending false',(select needs_approval from quotations order by created_at desc limit 1));
select pg_temp.ok('marketing: quotation margin hidden',(select count(*) from quotation_margins)=0);
update quotations set approved=true;
select pg_temp.ok('marketing: approve silently blocked (0 rows visible to update)',(select not approved from quotations limit 1));
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',false); set role authenticated;
select pg_temp.ok('md: sees quotation margin ~3.33%',(select margin_pct from quotation_margins limit 1)=3.33);
update quotations set approved=true; select pg_temp.ok('md: can approve',(select approved from quotations limit 1));
select pg_temp.fails('md: quotation price immutable',$$update quotations set price_per_kg=999$$);
-- SKU + artwork lock
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
insert into skus(customer_id,sku_code,description,structure,format) values('00000000-0000-0000-0000-000000000c01','RLS-SKU','test','PET/PE','Pouch');
insert into artworks(sku_id,revision,file_ref,status) select id,0,'r0.pdf','Draft' from skus where sku_code='RLS-SKU';
update artworks set status='Customer approved';
select pg_temp.fails('marketing: cannot lock artwork',$$update artworks set status='Locked'$$);
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',false); set role authenticated;
update artworks set status='Locked',locked=true;
select pg_temp.fails('md: locked artwork cannot be edited',$$update artworks set file_ref='hack.pdf'$$);
-- orders: marketing enters PO, cannot release; md releases -> ORD number
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
insert into orders(enquiry_id,customer_id,sku_id,owner_id,po_no,po_qty,po_price) select e.id,e.customer_id,s.id,e.owner_id,'PO-RLS',5000,155 from enquiries e, skus s where e.product='RLS test pouch' and s.sku_code='RLS-SKU';
select pg_temp.fails('marketing: cannot release order',$$update orders set released=true, confirmed_date=current_date+10$$);
select pg_temp.ok('marketing: order still unreleased',(select not released from orders where po_no='PO-RLS'));
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',false); set role authenticated;
select pg_temp.fails('md: release without confirmed date blocked',$$update orders set released=true where po_no='PO-RLS'$$);
update orders set released=true, confirmed_date=current_date+10, released_at=now() where po_no='PO-RLS';
select pg_temp.ok('md: release assigns ORD number',(select order_no ~ '^ORD-\d{4}-\d{4}$' from orders where po_no='PO-RLS'));
insert into order_stages(order_id,seq,name,dept_role) select id,1,'Material planning','planning' from orders where po_no='PO-RLS';
insert into order_stages(order_id,seq,name,dept_role) select id,2,'Printing','factory_manager' from orders where po_no='PO-RLS';
insert into order_stages(order_id,seq,name,dept_role) select id,3,'Packing','dispatch' from orders where po_no='PO-RLS';
-- departments update only their own stages
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000006',false); set role authenticated;
update order_stages set status='Done' where name='Material planning';
update order_stages set status='Done' where name='Printing';
select pg_temp.ok('planning: updated own stage',(select status from order_stages where name='Material planning')='Done');
select pg_temp.ok('planning: factory stage untouched',(select status from order_stages where name='Printing')='Pending');
select pg_temp.fails('planning: Delayed needs reason/recovery/revised date',$$update order_stages set status='Delayed' where name='Material planning'$$);
select pg_temp.fails('planning: cannot edit customers',$$insert into customers(name,mobile) values('x','1')$$);
select pg_temp.ok('planning: costing hidden',(select count(*) from costings)=0);
-- dispatch: dispatch + invoice; executive sees own invoice only
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000007',false); set role authenticated;
insert into invoices(invoice_no,customer_id,order_id,amount,due_date,exec_id) select 'INV-RLS',customer_id,id,300000,current_date+30,owner_id from orders where po_no='PO-RLS';
insert into dispatches(order_id,qty,date,invoice_no) select id,2000,current_date,'INV-RLS' from orders where po_no='PO-RLS';
update order_stages set status='Done' where name='Packing';
select pg_temp.ok('dispatch: updated own Packing stage',(select status from order_stages where name='Packing')='Done');
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
select pg_temp.ok('marketing owner: sees own invoice',(select count(*) from invoices where invoice_no='INV-RLS')=1);
insert into collections(invoice_id,amount,date) select id,100000,current_date from invoices where invoice_no='INV-RLS';
select pg_temp.ok('marketing owner: recorded collection',(select count(*) from collections)=1);
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000004',false); set role authenticated;
select pg_temp.ok('other marketing exec: invoice hidden',(select count(*) from invoices where invoice_no='INV-RLS')=0);
select pg_temp.ok('other marketing exec: collections hidden',(select count(*) from collections)=0);
-- incentives: server-side; marketing gets own lines without margin
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',false); set role authenticated;
update enquiries set stage='Won', won_at=now() where product='RLS test pouch';
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
select pg_temp.ok('marketing: own incentive line, margin hidden',(select count(*)=1 and bool_and(margin_pct is null) from incentive_lines()));
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000004',false); set role authenticated;
select pg_temp.ok('other exec: no incentive lines',(select count(*) from incentive_lines())=0);
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',false); set role authenticated;
select pg_temp.ok('md: incentive line with margin',(select bool_and(margin_pct is not null) from incentive_lines()));
-- complaints, HR admin, deactivated user, audit
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000003',false); set role authenticated;
insert into complaints(customer_id,description) values('00000000-0000-0000-0000-000000000c01','seal leak');
select pg_temp.ok('complaint number generated by DB',(select cmp_no ~ '^CMP-' from complaints limit 1));
update profiles set role='md' where id=auth.uid();
select pg_temp.ok('marketing: role unchanged',(select role from profiles where id=auth.uid())='marketing');
select pg_temp.ok('marketing: audit log hidden',(select count(*) from audit_log)=0);
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000009',false); set role authenticated;
select pg_temp.ok('deactivated user: sees no customers',(select count(*) from customers)=0);
reset role; select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',false); set role authenticated;
update profiles set territory='South' where email='mkt@rls.test';
select pg_temp.ok('hr_admin: edits profiles',(select territory from profiles where email='mkt@rls.test')='South');
select pg_temp.ok('hr_admin: sees all costing & margins',(select count(*) from costing_margins)>0 and (select count(*) from quotation_margins)>0);
select pg_temp.ok('hr_admin: audit log populated for all writes',(select count(distinct table_name) from audit_log)>=10);
reset role;
